function normalizePhone(p){ let s = String(p||'').replace(/[\s\-\(\)\+]/g,''); if(s.startsWith('0')) s = '254' + s.slice(1); return s; }
function dedupeBotRecords() {
  const seen = new Map();
  for (const b of botRecords) { const num = normalizePhone(b.number || b.phoneNumber || ''); if (!num) continue; if (!seen.has(num)) seen.set(num, { ...b, number: num }); else { const old = seen.get(num); if (new Date(b.updatedAt || b.createdAt || 0) > new Date(old.updatedAt || old.createdAt || 0)) seen.set(num, { ...old, ...b, number: num, ownerId: old.ownerId || b.ownerId }); } }
  const cleaned = [...seen.values()]; if (cleaned.length !== botRecords.length) { botRecords = cleaned; saveJsonFile(BOTS_FILE, botRecords); } return botRecords;
}
