function uniqueBots(list) { const m = new Map(); for (const b of (list || botRecords)) { const num = normalizePhone(b.number || ''); if (num && !m.has(num)) m.set(num, b); } return [...m.values()]; }
function normalizeBotState(value, info) { const raw = String(value || '').toLowerCase().trim(); if ((info && typeof info === 'object' && info.connected === true) || ['online','connected','open','active','ready'].includes(raw)) return 'online'; if (['offline','close','closed','disconnected','logged_out','logout','dead'].includes(raw)) return 'offline'; if (['pairing','connecting','qr','starting','reconnecting'].includes(raw)) return 'pairing'; return raw || 'offline'; }
function countBots() { const uniq = uniqueBots(); const online = uniq.filter(b => normalizeBotState(typeof b.state === 'object' ? b.state.state : b.state) === 'online').length; return { total: uniq.length, online, offline: uniq.length - online, unique: uniq.length }; }
