async function fetchFromEngine(base, route, options) { const response = await fetch(base + route, { ...(options || {}), headers: { 'content-type': 'application/json', 'x-pair-bridge-key': PAIR_BRIDGE_KEY, ...((options || {}).headers || {}) }, signal: AbortSignal.timeout(30000) }); const text = await response.text().catch(() => ''); let data = {}; try { data = text ? JSON.parse(text) : {}; } catch (_) { data = { raw: text }; } if (!response.ok || data.success === false) { const error = new Error(data.error || data.raw || 'WhatsApp engine request failed'); error.status = response.status || 502; error.code = data.code; error.data = data; throw error; } return data; }
async function engineFetch(route, options) { let lastErr = null; for (const base of ENGINE_URLS) { try { return await fetchFromEngine(base, route, options); } catch (e) { lastErr = e; if (e.status === 409 || e.status === 400) throw e; } } throw lastErr || new Error('All engines offline'); }
async function engineFetchAll(route, options) { const results = await Promise.all(ENGINE_URLS.map(async (base) => { try { return await fetchFromEngine(base, route, options); } catch (_) { return null; } })); return results.filter(Boolean); }
async function getRealEngineNumbers() { const all = await engineFetchAll('/api/count'); let numbers = []; for (const d of all) { if (Array.isArray(d.numbers)) numbers.push(...d.numbers.map(normalizePhone)); else if (d.bots && typeof d.bots === 'object') numbers.push(...Object.keys(d.bots).map(normalizePhone)); } if (numbers.length) return [...new Set(numbers.filter(n => /^\d{8,15}$/.test(n)))]; try { const all2 = await engineFetchAll('/api/status'); for (const d of all2) if (d.bots) numbers.push(...Object.keys(d.bots).map(normalizePhone)); if (numbers.length) return [...new Set(numbers.filter(n => /^\d{8,15}$/.test(n)))]; } catch {} return null; }
async function syncBotRecordsWithEngine() { try { const real = await getRealEngineNumbers(); if (real === null) return false; const realSet = new Set(real); const before = botRecords.length; const now = Date.now(); botRecords = botRecords.filter(b => { const num = normalizePhone(b.number); if (realSet.has(num)) return true; const age = now - new Date(b.createdAt || b.updatedAt || 0).getTime(); if (b.state === 'pairing' && age < 10 * 60 * 1000) return true; return false; }); for (const num of real) { if (!botRecords.some(b => normalizePhone(b.number) === num)) botRecords.push({ ownerId: '', username: '', number: num, state: 'online', createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), fromEngineSync: true }); } if (botRecords.length !== before) saveJsonFile(BOTS_FILE, botRecords); return true; } catch (_) { return false; } }
