function publicUser(u) { if (!u) return null; const x = { ...u }; delete x.password; delete x.providerId; delete x.email; delete x.phone; x.avatar = u.avatar || u.photo || ''; x.photo = u.photo || u.avatar || ''; x.cover = u.cover || ''; x.isAdmin = !!(u.isAdmin || isOwner(u.email, u.phone)); x.isPremium = isPremiumUser(u); x.proPlan = x.isPremium; x.isVerified = !!(x.isAdmin || x.isPremium); x.verified = x.isVerified; x.followersCount = (u.followers || []).length; x.followingCount = (u.following || []).length; x.likesCount = Number(u.likes || 0); x.botSpaces = Number(u.botSpaces || (x.isPremium ? PREMIUM_SLOTS : FREE_SLOTS)); x.usedSpaces = uniqueBots(botRecords.filter(b => b.ownerId === u.id)).length; x.coins = Number(u.coins || 0); return x; }
function tokenFor(u) { const isAdmin = !!(u.isAdmin || isOwner(u.email, u.phone)); const isPremium = isPremiumUser(u); return jwt.sign({ id: u.id, username: u.username, isAdmin, isPremium, isVerified: isAdmin || isPremium }, SECRET, { expiresIn: '30d' }); }
function auth(req, res, next) { const h = req.headers.authorization || ''; const token = req.headers['x-auth-token'] || h.replace(/^Bearer\s+/i, ''); req.user = null; if (token) { try { req.user = jwt.verify(token, SECRET); } catch (_) {} } next(); }
