botRecords.forEach(b=>{ if(b.botPassword && !botPasswords[normalizePhone(b.number)]) botPasswords[normalizePhone(b.number)] = b.botPassword; });
function makeBotPassword(){
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let p = '';
  for(let i=0;i<8;i++) p += chars[Math.floor(Math.random()*chars.length)];
  return p;
}
// Get or create bot password - BOT brings password when it connects
function getOrCreateBotPassword(number, ownerUser){
  const n = normalizePhone(number);
  let pw = botPasswords[n] || '';
  const rec = botRecords.find(b=> normalizePhone(b.number)===n);
  if(!pw && rec && rec.botPassword) pw = rec.botPassword;
  if(!pw){
    pw = makeBotPassword();
    botPasswords[n] = pw; saveBotPass();
    if(rec){ rec.botPassword = pw; saveJsonFile(BOTS_FILE, botRecords); }
    if(ownerUser){ addUserNotification(ownerUser, 'bot_password', 'Your Bot Password 🔑', 'Bot +'+n+' deployed! Your bot password is: '+pw+' - Use it in Manage Bot to Sign In.', {number:n, botPassword:pw}); }
  }
  return pw;
}

