app.get('/api/auth/:provider/callback', async (req, res) => { const provider = String(req.params.provider || '').toLowerCase(); const fail = msg => res.redirect('/?authError=' + encodeURIComponent(msg)); try { if (!['google', 'github'].includes(provider)) return res.status(404).send('Unsupported provider'); const st = jwt.verify(String(req.query.state || ''), SECRET); if (st.provider !== provider) return fail('Sign-in state mismatch.'); if (req.query.error || !req.query.code) return fail('Sign-in was cancelled.'); const cfg = oauth(provider); const tr = await fetch(provider === 'google' ? 'https://oauth2.googleapis.com/token' : 'https://github.com/login/oauth/access_token', { method: 'POST', headers: { Accept: 'application/json', 'Content-Type': 'application/json' }, body: JSON.stringify({ client_id: cfg.id, client_secret: cfg.secret, code: req.query.code, redirect_uri: cfg.callback, grant_type: 'authorization_code' }) }); const td = await tr.json(); if (!tr.ok || !td.access_token) return fail('OAuth token exchange failed.'); const headers = { Authorization: 'Bearer ' + td.access_token, Accept: 'application/json', 'User-Agent': 'KING-MD-V4' }; let profile, email, picture = ''; if (provider === 'google') { const pr = await fetch('https://www.googleapis.com/oauth2/v2/userinfo', { headers }); profile = await pr.json(); if (!pr.ok || !profile.id || !profile.email || profile.verified_email === false) return fail('Google did not return a verified email.'); email = profile.email.toLowerCase(); picture = profile.picture || ''; } else { const pr = await fetch('https://api.github.com/user', { headers }); profile = await pr.json(); if (!pr.ok || !profile.id) return fail('Could not read your GitHub profile.'); email = profile.email && profile.email.toLowerCase(); if (!email) { const er = await fetch('https://api.github.com/user/emails', { headers }); const es = er.ok ? await er.json() : []; const e = Array.isArray(es) && (es.find(x => x.primary && x.verified) || es.find(x => x.verified)); email = e && e.email && e.email.toLowerCase(); } picture = profile.avatar_url || ''; } if (!email) return fail('Your provider account needs a verified email address.'); let u = users.find(x => x.email && x.email.toLowerCase() === email); if (u) { u.provider = provider; u.providerId = String(profile.id); if (!u.photo && picture) { u.photo = picture; u.avatar = picture; } if(isOwner(email, u.phone)){ u.isAdmin = true; u.isVerified = true; u.isPremium = true; } saveUsers(); const code = crypto.randomBytes(32).toString('hex'); pending.set(code, { token: tokenFor(u), at: Date.now() }); return res.redirect((st.returnTo === 'app' ? '/app.html' : '/') + '?authCode=' + encodeURIComponent(code)); } const onb = crypto.randomBytes(32).toString('hex'); onboarding.set(onb, { provider, providerId: String(profile.id), email, picture, suggestedFirstName: String(profile.given_name || profile.name || profile.login || '').split(/\s+/)[0], suggestedLastName: String(profile.family_name || (profile.name || '').split(/\s+/).slice(1).join(' ')), at: Date.now() }); res.redirect((st.returnTo === 'app' ? '/app.html' : '/') + '?onboardToken=' + encodeURIComponent(onb)); } catch (e) { return fail('Sign-in failed.'); } });
