app.post('/api/bots/status', async (req, res) => { const nums = Array.isArray(req.body && req.body.numbers) ? [...new Set(req.body.numbers.map(normalizePhone).filter(n => /^\d{8,15}$/.test(n)))] .slice(0, 30) : []; if (!nums.length) return res.json({ success: true, bots: {} }); try { const all = await engineFetchAll('/api/status?numbers=' + encodeURIComponent(nums.join(','))); const merged = {}; for (const d of all) Object.assign(merged, d.bots || {}); const account = currentUser(req); const normalized = {}; for (const n of nums) { const info = merged[n]; const st = normalizeBotState(info && typeof info === 'object' ? info.state : info, info); normalized[n] = { state: st, connected: st === 'online', updatedAt: (info && info.updatedAt) || null }; } if (account) { botRecords.filter(b => nums.includes(normalizePhone(b.number))).forEach(b => { const nextState = normalized[normalizePhone(b.number)].state; const oldState = typeof b.state === 'object' ? b.state.state : b.state; if (oldState !== nextState && (nextState === 'online' || nextState === 'offline')) { addUserNotification(account, 'bot_status', nextState === 'online' ? 'WhatsApp bot connected' : 'WhatsApp bot disconnected', '+' + b.number + (nextState === 'online' ? ' is now active.' : ' is offline.'), { number: b.number, state: nextState }); } b.state = nextState; b.updatedAt = new Date().toISOString(); }); saveJsonFile(BOTS_FILE, botRecords); saveUsers(); } res.json({ success: true, bots: normalized }); } catch (e) { res.status(502).json({ success: false, error: e.message || 'Engine status unavailable', bots: {} }); } });
