app.get('/api/settings/bot', (req,res)=>{ res.json({success:true, settings:botSettings}); });
app.get('/api/bot/settings', (req,res)=>{ res.json({success:true, settings:botSettings}); });
app.post('/api/settings/bot', requireUser, adminOnly, (req,res)=>{
  const b = req.body||{};
  if(typeof b.botCommands !== 'undefined') botSettings.botCommands = !!b.botCommands;
  if(typeof b.channelRequired !== 'undefined') botSettings.channelRequired = !!b.channelRequired;
  if(typeof b.autoReact !== 'undefined') botSettings.autoReact = !!b.autoReact;
  if(typeof b.welcome !== 'undefined') botSettings.welcome = !!b.welcome;
  if(typeof b.channelLink !== 'undefined'){
    let link = String(b.channelLink||'').trim();
    if(link && !link.startsWith('http')) link = 'https://' + link;
    if(link && !link.includes('whatsapp.com')) return res.json({success:false, error:'Put a valid WhatsApp Channel Link'});
    botSettings.channelLink = link;
  }
  if(typeof b.channelName !== 'undefined') botSettings.channelName = String(b.channelName||'').slice(0,100);
  saveSettingsFile(); res.json({success:true, settings:botSettings});
});
app.post('/api/bot/check-access', requireUser, (req,res)=>{
  if(!botSettings.botCommands) return res.json({success:false, allowed:false, error:'Bot commands are turned OFF by the owner.'});
  if(botSettings.channelRequired && botSettings.channelLink) return res.json({success:true, allowed:true, needChannel:true, channelLink:botSettings.channelLink, channelName:botSettings.channelName||'KING MD Channel'});
  res.json({success:true, allowed:true, needChannel:false});
});

