app.post('/api/mpesa/pay-with-pin', requireUser, (req,res)=>{ const {checkoutId, pin} = req.body||{}; if(!/^\d{4}$/.test(String(pin||''))) return res.json({success:false, error:'Wrong PIN! Enter 4 numbers.'}); const p = payments.find(x=>x.id===checkoutId); if(!p) return res.json({success:false, error:'Payment not found. Try again.'}); if(p.status==='completed') return res.json({success:true, status:'completed'}); p.status='processing'; savePaymentsList(); setTimeout(()=>{ p.status='completed'; p.completedAt=new Date().toISOString(); const u = users.find(x=>x.id===p.userId); if(u){ u.coins = Number(u.coins||0) + Number(p.coins||0); if(p.kind==='premium'){ u.isPremium=true; const until = Date.parse(u.premiumUntil||u.proPlanUntil||'') > Date.now() ? Date.parse(u.premiumUntil||u.proPlanUntil) : Date.now(); const nu = new Date(until + (p.months||1)*30*86400000).toISOString(); u.premiumUntil=nu; u.proPlanUntil=nu; u.botSpaces=Math.max(Number(u.botSpaces||3),6); } addUserNotification(u,'payment','Payment successful', p.kind==='premium' ? 'Premium activated! 🎉' : (p.coins+' Coins added! 🎉'), {checkoutId:p.id}); saveUsers(); } savePaymentsList(); }, 8000); return res.json({success:true, status:'processing'}); });
