app.post('/api/bot/forgot-password', requireUser, (req,res)=>{
  const b=req.body||{}; let number = normalizePhone(b.number||b.botNumber||'');
  if(!/^\d{8,15}$/.test(number)) return res.json({success:false, error:'Enter your bot number first'});
  const rec = botRecords.find(x=> normalizePhone(x.number)===number && x.ownerId===req.account.id);
  if(!rec && !isOwner(req.account.email, req.account.phone)) return res.json({success:false, error:'Bot not found for your account'});
  const newPass = makeBotPassword();
  botPasswords[number]=newPass; saveBotPass();
  if(rec){ rec.botPassword=newPass; saveJsonFile(BOTS_FILE, botRecords); }
  addUserNotification(req.account, 'bot_password', 'Bot password reset', 'Your new bot password for +'+number+' is: '+newPass, {number, botPassword:newPass});
  saveUsers();
  return res.json({success:true, newPassword:newPass, message:'New password created. Check notifications.'});
});
app.post('/api/bot/reset-password', requireUser, (req,res)=>{
  const b=req.body||{}; let number = normalizePhone(b.number||'');
  const newPass = String(b.newPassword||'').trim();
  if(newPass.length<4) return res.json({success:false, error:'New password must be 4+ characters'});
  botPasswords[number]=newPass; saveBotPass();
  const rec = botRecords.find(x=> normalizePhone(x.number)===number);
  if(rec){ rec.botPassword=newPass; saveJsonFile(BOTS_FILE, botRecords); }
  return res.json({success:true, message:'Bot password updated'});
});
// BOT itself sends its password to SERVER - server is the only place that saves it
app.post('/api/bot/set-password-from-bot', async (req,res)=>{
  const b = req.body||{};
  if(b.key !== PAIR_BRIDGE_KEY && b.bridgeKey !== PAIR_BRIDGE_KEY) return res.json({success:false, error:'Wrong key'});
  let number = normalizePhone(b.number || b.botNumber || '');
  const password = String(b.password || b.botPassword || '').trim();
  if(!/^\d{8,15}$/.test(number) || !password) return res.json({success:false, error:'Need number + password'});
  botPasswords[number] = password; saveBotPass();
  const rec = botRecords.find(x=> normalizePhone(x.number)===number);
  if(rec){ rec.botPassword = password; rec.updatedAt = new Date().toISOString(); saveJsonFile(BOTS_FILE, botRecords); }
  if(rec && rec.ownerId){
    const u = users.find(x=>x.id===rec.ownerId);
    if(u){ addUserNotification(u, 'bot_password', 'Bot Password Received 🔑', 'Your bot +'+number+' sent its password: '+password+' - Use it in Manage Bot.', {number, botPassword: password}); saveUsers(); }
  }
  res.json({success:true, message:'Bot password saved'});
});
